    LANGUAGE_WRAPPER = 'In a math contest, consider the monic degree-6 polynomial f(x) = (x^2 - {t}x - {u})(x^4 + {v}). Let \\alpha be the smallest positive real root of f(x)=0 (i.e., the positive root of x^2 - {t}x - {u}=0). Let the exponent be n = {n}. Define the composite modulus {s_modulus} = {p1}^{ {e1} } \\cdot {p2}^{ {e2} } \\cdot {p3}^{ {e3} }. Set N to be the remainder when the nearest integer to \\alpha^{n} is divided by {s_modulus}. Three inspectors evaluate an ID m using modular rules: Inspector A accepts m iff its residue modulo {p1}^{ {e1} } is a non-zero {k1}-th power residue; Inspector B uses modulo {p2}^{ {e2} } with {k2}-th power residues; Inspector C uses modulo {p3}^{ {e3} } with {k3}-th power residues. An ID is qualified iff all three inspectors pass it. Let M = {lambda} \\cdot {s_modulus}. Within the range 1 \\le m \\le M, how many qualified IDs are there? After solving, please output your final answer in the format: ### The final answer is: \\boxed{<answer>}.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
import math
# Choose three distinct odd primes
primes = [7, 11, 13, 17, 19, 23, 29, 31]
p1, p2, p3 = rng.sample(primes, 3)
# Ensure at least one prime power modulus has exponent 2 (for difficulty)
while True:
    e1 = rng.choice([1, 2])
    e2 = rng.choice([1, 2])
    e3 = rng.choice([1, 2])
    if (e1 == 2) or (e2 == 2) or (e3 == 2):
        break
# Choose k_i (degrees of power residues), ensure at least one gcd(phi, k) > 1
def phi_p_pow(p, e):
    return (p - 1) * (p ** (e - 1))
while True:
    k1 = rng.randint(2, p1 - 1)
    k2 = rng.randint(2, p2 - 1)
    k3 = rng.randint(2, p3 - 1)
    g1 = math.gcd(k1, phi_p_pow(p1, e1))
    g2 = math.gcd(k2, phi_p_pow(p2, e2))
    g3 = math.gcd(k3, phi_p_pow(p3, e3))
    # Enforce non-triviality: at least one inspector does not accept all units
    if (g1 > 1) or (g2 > 1) or (g3 > 1):
        break
# Composite modulus
s_modulus = (p1 ** e1) * (p2 ** e2) * (p3 ** e3)
# Quadratic factor parameters
t = rng.randint(30, 80)
# Keep u small relative to t to force |beta| < 1 and rapidly decaying |beta|^n
u = rng.randint(1, max(1, t // 8))
v = rng.choice([1, 2, 3, 4])  # quartic has no real roots
n = rng.randint(20, 40)
# Verify nearest-integer property: beta negative and |beta|^n < 0.5
def check_quadratic(t, u, n):
    disc = t * t + 4 * u
    sqrt_disc = math.sqrt(disc)
    alpha = (t + sqrt_disc) / 2.0
    beta = (t - sqrt_disc) / 2.0
    # beta must be negative and small in magnitude
    if beta >= 0:
        return False, alpha, beta
    if abs(beta) >= 1:
        return False, alpha, beta
    if (abs(beta) ** n) >= 0.5:
        return False, alpha, beta
    return True, alpha, beta
# Try to satisfy the check; adjust u or n if needed
ok, alpha, beta = check_quadratic(t, u, n)
attempts = 0
while not ok and attempts < 100:
    # Make u smaller or increase n to improve decay
    u = max(1, u // 2)
    n = rng.randint(25, 50)
    ok, alpha, beta = check_quadratic(t, u, n)
    attempts += 1
if not ok:
    # Fall back to safe parameters
    u = max(1, t // 12)
    n = 40
    ok, alpha, beta = check_quadratic(t, u, n)
    if not ok:
        # As a last resort, shrink u further
        u = 1
        n = 40
        ok, alpha, beta = check_quadratic(t, u, n)
# Choose lambda (number of full CRT blocks)
lambda_mult = rng.choice([2, 3, 4])
return {
    't': t,
    'u': u,
    'v': v,
    'n': n,
    'p1': p1,
    'e1': e1,
    'k1': k1,
    'p2': p2,
    'e2': e2,
    'k2': k2,
    'p3': p3,
    'e3': e3,
    'k3': k3,
    's_modulus': s_modulus,
    'lambda': lambda_mult
}

